import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG 转 WebP 是网站最容易的速度胜利之一。照片看起来一样，文件小三分之一，页面加载更快。</p>\n<p>每张照片只要几秒，整文件夹一次也能转。一切都在浏览器里运行，不用安装。</p>\n<p>这篇指南按步骤走，讲清哪些设置对干净的结果最重要。</p>\n<h2 id=\"before-you-start\">开始之前：需要准备什么</h2>\n<p>你只需要 JPG 文件和一个现代浏览器。Chrome、Edge、Firefox、Safari 都行，电脑和手机上都能用。</p>\n<p>找到画质最好的 JPG 原文件。转换变不出细节，所以从最高质量的副本开始，别从已经压缩过的缩略图开始。</p>\n<p>先弄清 WebP 文件要去哪里。网站要 80% 画质，打算放大看的照片要 85%。</p>\n<p>每张文件最大接受 25MB。涵盖高分辨率相机照片和大截图，不用任何准备。</p>\n<h2 id=\"step-1-open-tool\">第 1 步：打开 JPG 转 WebP 工具</h2>\n<p>在浏览器里打开<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>。Windows、Mac、Linux、ChromeOS、安卓、iOS 上都能用。</p>\n<p>你会看到上传区域、画质滑块和转换按钮。整个任务就是这三个控件。</p>\n<p>不用注册账号，什么都不上传。转换在你的设备上进行，客户照片和个人图片都很看重这一点。</p>\n<p>手机上也一样，在移动浏览器里用。点上传区域，从相册里选照片。</p>\n<h2 id=\"step-2-upload\">第 2 步：上传 JPG 文件</h2>\n<p>把 JPG 文件拖到上传区域，或者点一下打开文件选择器。.jpg 和 .jpeg 扩展名都接受。</p>\n<p>一次可以上传很多文件做批量。每张都会显示成一张卡片，带名字、尺寸和大小，确认传的是正确的文件。</p>\n<p>检查每张卡片上的尺寸。WebP 会精确保留 JPG 的像素宽高，传错的文件在这里很容易发现。</p>\n<p>电脑上也可以用 Ctrl+V 粘贴复制的图片。JPG 在剪贴板里、从别的软件复制过来时，这个办法很方便。</p>\n<h2 id=\"step-3-quality\">第 3 步：设置画质滑块</h2>\n<p>画质滑块控制 WebP 编码器保留多少细节。大多数网站照片用 80% 就对了。</p>\n<p>加载速度最重要的大图用 75%。轻微柔和在全屏尺寸下看不见，文件还能再小一点。</p>\n<p>访客会放大的产品照片用 85%。多出来的画质能保护买家仔细检查的精细细节。</p>\n<p>别人要看的照片别低于 70%。柔和会变得可见，省下来的那点体积比不上损伤。</p>\n<h2 id=\"step-4-convert\">第 4 步：转换文件</h2>\n<p>点“转换”按钮。工具解码每张 JPG，在画布上重绘，编码成 WebP。</p>\n<p>转换很快，通常每张照片一两秒。文件更大时稍久一点，因为要编码的像素更多。</p>\n<p>每张卡片都会更新，显示新 WebP 的大小和原来 JPG 的大小。好的转换在大多数照片上能显示 25% 到 35% 的节省。</p>\n<p>某个文件失败时，读一下错误提示。损坏的 JPG 或名字不对的文件是最常见的原因，其余批量继续转换。</p>\n<h2 id=\"step-5-preview\">第 5 步：预览并检查节省</h2>\n<p>点卡片上的“对比”，并排查看 JPG 和 WebP。拖动分割线，检查脸部、文字和精细细节。</p>\n<p>文件大小也要检查。WebP 比 JPG 还大，说明原图已经被重度压缩，这张文件留着 JPG 就好。</p>\n<p>颜色也要看。大多数照片的颜色保持准确，特别饱和的图片在转换中可能轻微偏移。</p>\n<p>结果发软时，把画质调高五点再转一次。原 JPG 还留在队列里，不用重新上传。</p>\n<h2 id=\"step-6-download\">第 6 步：下载 WebP 文件</h2>\n<p>点单张卡片上的“下载”，保存一张 WebP。文件名保留原名，换成 .webp 后缀。</p>\n<p>批量时点“全部下载”，拿到一个装着所有转好 WebP 的 ZIP 包。比一张一张下载快得多。</p>\n<p>使用之前检查一次下载好的文件。在浏览器里打开一张 WebP，确认显示正确。</p>\n<p>原 JPG 也留着。目的地拒收 WebP 时，可以直接上传 JPG，不用重新转换。</p>\n<ol>\n<li>打开 JPG 转 WebP 工具，上传 JPG 文件。</li>\n<li>网站用的画质滑块设到 80%。</li>\n<li>转换后检查每张卡片上的节省。</li>\n<li>用“对比”预览，再下载 WebP 文件。</li>\n</ol>\n<h2 id=\"converting-a-folder\">转换整文件夹博客图片</h2>\n<p>博客图片文件夹里的 JPG 一次全选。它们进入队列，一次点击全部转成 WebP。</p>\n<p>整文件夹用同一个画质设置。图片共用一个页面时，一致性很重要，画质参差不齐看起来不均匀。</p>\n<p>转换后看批量汇总。它把所有文件的节省加起来，好的批量总体常常能缩小三分之一。</p>\n<p>把 WebP 文件上传到网站，替代 JPG。更新图片引用，测试页面，确认所有内容显示正确。</p>\n<h2 id=\"changing-quality-after\">第一次转换后改画质</h2>\n<p>转换后不用重新上传就能改画质滑块。原 JPG 还留在队列里，新设置一次点击就到。</p>\n<p>先试 80%，再试 75%，对比两个结果。差别常常看不见，小的那个文件就是正确的选择。</p>\n<p>单张重要照片，85% 和 90% 也试试。最好的设置是看不出任何差别的最低档。</p>\n<p>切换设置前，先下载每个版本。下载按钮保存的是当前转换，改动之前先拿到它。</p>\n<h2 id=\"fixing-problems\">常见问题怎么解决</h2>\n<p>WebP 出来比 JPG 大，说明原图已经被重度压缩。这张文件留着 JPG，继续处理下一张。</p>\n<p>图片发软，说明画质太低。把滑块调到 85%，用原 JPG 再转一次。</p>\n<p>文件转失败，检查它是不是真正的 JPG。名为 .jpg、实际却是 PNG 或 WebP 的文件会让解码器糊涂。</p>\n<p>颜色看起来偏移了，源文件可能有不常见的颜色配置文件。仔细对比 WebP 和 JPG，偏移重要时留着 JPG。</p>\n<h2 id=\"uploading-to-your-site\">把 WebP 上传到网站</h2>\n<p>转好的 WebP 文件像其他图片一样上传到媒体库。WordPress、Shopify、Wix 现在都接受 WebP 上传。</p>\n<p>先测试一张图片。上传它，查看页面，在电脑和手机上确认显示正确。</p>\n<p>老浏览器用 JPG 备用，和 WebP 一起提供。大多数平台自动处理，或者在 HTML 里用 picture 元素。</p>\n<p>切换后测量页面速度。WebP 图片的页面应该明显加载更快，这就是转换的全部意义。</p>\n<h2 id=\"converting-blog-library\">转换博客的图片库</h2>\n<p>博客的图片库几年下来不断增长，一次全部转换是个项目，不是杂活。按批次计划，一次一个月或一个分类。</p>\n<p>从访问量最高的文章开始，因为它们最受益于更快的加载。热门文章的 WebP 图片比冷门文章更好地服务成千上万的读者。</p>\n<p>每批用 80% 画质转换，再更新文章里的图片引用。坏掉的引用比慢速图片更糟，更新后检查每篇文章。</p>\n<p>媒体库里留着 JPG 原文件做备用。读者浏览器显示不了 WebP 时加载 JPG 版本，没人会看到破损图片。</p>\n<p>用一张简单的清单跟踪进度。打勾的月份做完了，没打勾的还在等，这样文章不会被转两次，也不会漏转。</p>\n<h2 id=\"converting-product-photos\">给网店转换产品照片</h2>\n<p>产品照片需要用心，因为顾客会放大看。转 80% 到 85% 画质，布料纹理、缝线、小细节保持可见。</p>\n<p>转换前按类别分类产品。鞋子、衬衫、配饰可能需要不同的设置，先分类意味着每组一次干净的批量。</p>\n<p>转换后检查三四个产品，而不是全部五百个。这几个没问题，其余的也会没问题，因为整批设置相同。</p>\n<p>上传 WebP 文件，更新产品列表。在电脑和手机上测试几个产品页面，确认图片显示正确。</p>\n<p>JPG 原文件也留着，有些平台要求 JPG。在亚马逊和自家网店同时上架的产品，两种格式都要准备好。</p>\n<h2 id=\"converting-portfolio-photos\">给作品集转换照片</h2>\n<p>作品集必须看起来完美，转换设置也要反映这一点。用 85% 画质，客户近距离放大时图片依然锐利。</p>\n<p>先选最强的图片，再按重要性顺序转换。主图最值得用心，因为它决定了整个作品集的第一印象。</p>\n<p>转换后逐张检查图片，不只是抽查。作品集图片不多，每张都很重要，全部快速检查一次值得。</p>\n<p>用 WebP 文件更新作品集网站，在电脑和手机上测试。作品集上的破损图片就是丢掉的客户，所以确认每张图片都加载。</p>\n<p>JPG 原文件留在作品集文件夹里。客户要求 JPG 版本时，不用重新转换就能给。</p>\n<h2 id=\"converting-social-images\">给社交媒体转换图片</h2>\n<p>社交媒体平台会把上传内容转成自己的格式，源格式不如画质重要。高画质 WebP 输入比低画质 JPG 输入结果更好。</p>\n<p>上传前把图片转成 85% 画质的 WebP。平台压缩的工作量更小，最终图片看起来更干净。</p>\n<p>转换前先看平台偏好的尺寸。Instagram、Facebook、X 各有理想尺寸，尺寸不对靠转换修不好。</p>\n<p>带文字的图形用 85% 的 WebP，字母比 JPG 更锐利。平台压缩后文字依然可读，这正是图形的目的。</p>\n<p>下载转好的文件，直接从设备上传，别分享链接。直接上传能保留你选的画质，分享链接可能触发新一轮压缩。</p>\n<h2 id=\"updating-old-references\">更新旧的 JPG 引用</h2>\n<p>转换后，网站仍在引用旧 JPG 文件。更新这些引用是人们会忘的一步，忘了引用，WebP 文件就白白放着没人用。</p>\n<p>在网站里搜索转换后文件的图片引用。在内容里简单搜索 .jpg，就能找到每个需要更新的地方。</p>\n<p>更新引用指向 WebP 文件，JPG 留着做备用。picture 元素给现代浏览器提供 WebP、给其他浏览器提供 JPG。</p>\n<p>更新后的页面彻底测试。点遍网站、检查每张图片，确认没有破损，再进行下一批。</p>\n<p>测试后才删掉旧 JPG 引用。测试过、WebP 图片能用的页面是安全的，没测试过的改动可能藏着破损图片。</p>\n<h2 id=\"images-for-new-website-launch\">新网站上线前的图片转换</h2>\n<p>新网站上线需要每张图片从第一天起就是正确的格式。上线前把 JPG 照片转成 WebP，网站从第一个访客起就很快。</p>\n<p>上线图片一次批量转 80% 画质。照片看起来干净，文件小三分之一，每台设备上的页面加载都很快。</p>\n<p>发布前在电脑和手机上测试上线网站。上线当天出现破损图片是糟糕的第一印象，快速测试能发现它。</p>\n<p>媒体库里留着 JPG 原文件做备用。访客浏览器显示不了 WebP 时加载 JPG 版本，没人会看到破损图片。</p>\n<p>在项目笔记里记录格式选择。一行笔记能防止下一个人往应该用 WebP 的网站上传 JPG。</p>\n<p>整个流程就是这样：上传、设画质、转换、下载。想了解背景，请读<a href=\"/zh/blog/jpg-zhuan-webp-wanquan-zhinan/\">JPG 转 WebP 完全指南</a>；正面对决请看<a href=\"/zh/blog/jpg-vs-webp/\">JPG 与 WebP 对比</a>。图片是 PNG 而不是 JPG 时，<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>是对应的工具。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"怎么把一文件夹 JPG 博客图片转成 WebP？","answer":"在文件选择器里一次选文件夹里的所有 JPG，或者把文件夹拖到上传区域。画质设 80%，转换后下载 ZIP。把 WebP 文件上传到网站替代 JPG，再测试页面，确认所有内容显示正常。"},{"question":"转成 WebP 后能改画质吗？","answer":"可以。第一次转换后原 JPG 还留在队列里，移动画质滑块、再转一次就行，不用重新上传。切换设置前先下载每个版本，下载按钮保存的是当前转换。"},{"question":"产品照片用什么画质设置最好？","answer":"产品照片最好用 80% 到 85%，顾客会放大看、检查精细细节。低设置会糊掉布料纹理和小特征，可能丢掉销量。大图用 75% 就够了，全屏尺寸下轻微柔和看不见。"},{"question":"WebP 图片能在 WordPress 里用吗？","answer":"可以。WordPress 从 5.8 版起支持 WebP 上传，转好的文件像其他图片一样上传到媒体库。先测试一张图片确认显示正确，再上传其余批量。"},{"question":"JPG 转 WebP 离线能用吗？","answer":"页面加载好之后，转换在浏览器本地运行，不需要联网。只有第一次打开页面时需要网络。之后在关掉标签页之前，都可以离线转换 JPG。"},{"question":"WebP 文件在老设备上打不开怎么办？","answer":"用 WebP 转 JPG 工具把那张图片转回 JPG，老设备用 JPG。网站上同时提供 JPG 备用和 WebP，现代浏览器拿到更小的文件，老浏览器拿到兼容的文件。"}];
